var checkValid = function(matrix) {
    const n = matrix.length;
    for (let r = 0; r < n; r++) {
        if (new Set(matrix[r]).size !== n) return false;
    }
    for (let c = 0; c < n; c++) {
        const colSet = new Set();
        for (let r = 0; r < n; r++) {
            colSet.add(matrix[r][c]);
        }
        if (colSet.size !== n) return false;
    }
    return true;
};
